// Build the @font-face stylesheet with absolute URLs. Pass an empty
// string (or no argument) to get the relative version above.
export function buildFontFaceCss(origin = "") {
  if (!origin) return FONT_FACE_CSS;
  return FONT_FACE_CSS.replace(/\/fonts\//g, origin.replace(/\/$/, "") + "/fonts/");
}

export default FONT_CATALOG;
